    <button onClick={()=>void load()} className="h-9 rounded-lg bg-[#488391] px-3 text-xs font-bold text-white disabled:opacity-60" disabled={refreshing}>{refreshing?"Actualizando…":"Actualizar"}</button><button onClick={exportCsv} className="h-9 rounded-lg border border-[#488391] px-3 text-xs font-bold text-[#284c55]">Exportar CSV</button><button onClick={()=>window.print()} className="h-9 rounded-lg border border-[#488391] px-3 text-xs font-bold text-[#284c55]">Imprimir / PDF</button>
   </div>
   <div className="grid grid-cols-2 gap-3 lg:grid-cols-4 xl:grid-cols-6"><Kpi label="Por atender" value={fmt(pending)} help="Pendientes reportados por las áreas"/><Kpi label="En proceso" value={fmt(snapshot.summary.activeFlows)} help="Flujos operacionales activos"/><Kpi label="Por cerrar" value={fmt(snapshot.summary.attentionAreas+snapshot.summary.criticalAreas)} help="Áreas con atención o criticidad"/><Kpi label="Finalizados" value={fmt(finalizados)} help="Eventos con estado final recibido"/><Kpi label="Stock sano promedio" value={fmt(stockAverage,"%")} help="Promedio de áreas con métrica disponible"/><Kpi label="Volumen en flujo" value={fmt(flowVolume)} help="Volumen agregado del snapshot"/></div>
   <Panel title="Estado por área" subtitle={areas.length+" de "+snapshot.areas.length+" áreas"}><Table headers={["Área","Tipo","Estado","Stock sano","Actividad","Ocupación","Pendientes"]}>{areas.map(area=><tr key={area.id} className="border-t border-[#488391]/10"><Td strong>{area.name}</Td><Td>{AREA_TYPE[area.type]??area.type}</Td><Td><Badge tone={area.status}>{STATUS[area.status].label}</Badge></Td><Td>{fmt(area.metrics.stockHealth,"%")}</Td><Td>{fmt(area.metrics.activity)}</Td><Td>{fmt(area.metrics.occupancy,"%")}</Td><Td>{fmt(area.metrics.pending)}</Td></tr>)}</Table>{!areas.length&&<Empty/>}</Panel>
   <Panel title="Flujo de abastecimiento" subtitle={flows.length+" flujos visibles"}><Table headers={["Origen","Destino","Tipo","Volumen","Estado"]}>{flows.map(flow=><tr key={flow.id} className="border-t border-[#488391]/10"><Td strong>{areaMap.get(flow.from)??flow.from}</Td><Td>{areaMap.get(flow.to)??flow.to}</Td><Td>{FLOW_TYPE[flow.kind]??flow.kind}</Td><Td>{fmt(flow.volume)}</Td><Td><Badge tone={flow.status??"normal"}>{STATUS[flow.status??"normal"].label}</Badge></Td></tr>)}</Table>{!flows.length&&<Empty/>}</Panel>
   <Panel title="Eventos operacionales" subtitle={filteredEvents.length+" eventos · máximo 100 por consulta"} className="print-break"><Table headers={["Fecha","Evento","Área / recorrido","Severidad","Cantidad","Estado"]}>{filteredEvents.map(event=><tr key={event.id} className="border-t border-[#488391]/10"><Td>{when(event.occurredAt)}</Td><Td strong>{eventName(event)}</Td><Td>{event.areaId?areaMap.get(event.areaId)??event.areaId:(areaMap.get(event.from??"")??event.from??"—")+" → "+(areaMap.get(event.to??"")??event.to??"—")}</Td><Td><Badge tone={event.severity}>{STATUS[event.severity].label}</Badge></Td><Td>{fmt(typeof event.metadata?.quantity==="number"?event.metadata.quantity:undefined)}</Td><Td>{String(event.metadata?.status??"—")}</Td></tr>)}</Table>{!filteredEvents.length&&<Empty/>}</Panel>
   <footer className="flex flex-wrap justify-between gap-2 border-t border-[#488391]/15 pt-3 text-[10px] text-[#284c55]/60"><span>Hospital: {snapshot.hospitalId}</span><span>Corte del informe: {when(snapshot.generatedAt)}</span><span>Solo información operacional agregada; sin identidad clínica.</span></footer>
  </section>
 </main>
}
function Badge({tone,children}:{tone:Status;children:React.ReactNode}){const value=STATUS[tone];return <span className="inline-flex rounded-full px-2 py-1 text-[9px] font-bold uppercase tracking-wide" style={{background:value.bg,color:value.color}}>{children}</span>}
function Kpi({label,value,help}:{label:string;value:string;help:string}){return <article className="rounded-xl border border-[#488391]/15 bg-white p-3 shadow-sm"><p className="text-[9px] font-bold uppercase tracking-[.13em] text-[#284c55]/55">{label}</p><p className="mt-1 text-2xl font-black tabular-nums text-[#284c55]">{value}</p><p className="mt-1 text-[9px] leading-4 text-[#284c55]/55">{help}</p></article>}
function Panel({title,subtitle,className="",children}:{title:string;subtitle:string;className?:string;children:React.ReactNode}){return <section className={"overflow-hidden rounded-xl border border-[#488391]/15 bg-white shadow-sm "+className}><div className="flex flex-wrap items-center justify-between gap-2 px-4 py-3"><h2 className="text-sm font-bold">{title}</h2><span className="text-[10px] text-[#284c55]/55">{subtitle}</span></div>{children}</section>}
function Table({headers,children}:{headers:string[];children:React.ReactNode}){return <div className="overflow-x-auto"><table className="w-full min-w-[680px] border-collapse text-left text-[11px]"><thead className="bg-[#488391]/[.07] text-[9px] uppercase tracking-wide text-[#284c55]/65"><tr>{headers.map(header=><th key={header} className="px-4 py-2">{header}</th>)}</tr></thead><tbody>{children}</tbody></table></div>}
function Td({children,strong=false}:{children:React.ReactNode;strong?:boolean}){return <td className={"whitespace-nowrap px-4 py-2.5 "+(strong?"font-semibold":"text-[#284c55]/75")}>{children}</td>}
function Empty(){return <div className="border-t border-[#488391]/10 px-4 py-6 text-center text-xs text-[#284c55]/50">No hay registros para los filtros seleccionados.</div>}
function State({text,retry}:{text:string;retry?:()=>void}){return <div className="grid h-full min-h-[300px] place-items-center bg-[#f4f7f7] p-6"><div className="rounded-xl border border-[#488391]/15 bg-white p-5 text-sm text-[#284c55] shadow-sm">{text}{retry&&<button onClick={retry} className="ml-3 rounded-lg bg-[#488391] px-3 py-2 text-xs font-bold text-white">Reintentar</button>}</div></div>}
